const crypto = require('crypto')

// UUIDv7 (RFC 9562): 48-bit Unix ms timestamp + 74 random bits.
// Ids generated by one process are strictly increasing, even when many are produced in the
// same millisecond or the wall clock steps backwards: the 12-bit rand_a field is used as a
// monotonic counter and the timestamp is never allowed to go below the last one issued.
let lastMs = 0
let counter = 0

function formatUuid(bytes) {
  const hex = bytes.toString('hex')
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`
}

function buildUuidV7(ms, seq, randomTail) {
  const bytes = Buffer.alloc(16)
  bytes.writeUIntBE(ms, 0, 6)
  bytes[6] = 0x70 | ((seq >> 8) & 0x0f)
  bytes[7] = seq & 0xff
  randomTail.copy(bytes, 8, 0, 8)
  bytes[8] = (bytes[8] & 0x3f) | 0x80
  return formatUuid(bytes)
}

function uuidv7(nowMs = Date.now()) {
  let ms = Math.max(Math.floor(Number(nowMs) || 0), lastMs)
  if (ms === lastMs) {
    counter += 1
    if (counter > 0x0fff) {
      // 4096 ids in one millisecond: borrow the next millisecond to stay strictly ordered
      ms += 1
      counter = 0
    }
  } else {
    counter = crypto.randomInt(0, 0x0200)
  }
  lastMs = ms
  return buildUuidV7(ms, counter, crypto.randomBytes(8))
}

// For backfilling historic rows: time-ordered by the row's own timestamp, not monotonic state.
function uuidv7ForTimestamp(timestampMs) {
  const ms = Math.max(0, Math.floor(Number(timestampMs) || 0))
  return buildUuidV7(ms, crypto.randomInt(0, 0x1000), crypto.randomBytes(8))
}

function uuidv7Timestamp(uuid) {
  const hex = String(uuid || '').replace(/-/g, '')
  if (hex.length !== 32) return null
  return parseInt(hex.slice(0, 12), 16)
}

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i

function isUuid(value) {
  return UUID_PATTERN.test(String(value || ''))
}

module.exports = { uuidv7, uuidv7ForTimestamp, uuidv7Timestamp, isUuid }
